import sys
sys.path.append('storage/ariadne')

import jax.numpy as jnp
import optax
from models import RC_DiagLDSFactorModel

BASE_SEED = 42
BATCH_SIZE = 8

def _define_hyperparameters():
    # Use the best-performing DiagLDS capacity seen so far
    return {
        'learning_rate': 0.001,
        'rank_k': 48,
        'hidden_size': 64,
        'normalize_loadings': True
    }

class Wrapper:
    def __init__(self, rank_k=48, hidden_size=64, normalize_loadings=True):
        self.model = RC_DiagLDSFactorModel(
            rank_k=rank_k,
            hidden_size=hidden_size,
            normalize_loadings=normalize_loadings
        )
        self.needs_rng = False

    def init(self, rng_key, dummy_input):
        return self.model.init(rng_key, dummy_input, training=True)

    def apply(self, params, x, training=False, mutable=None, rngs=None):
        return self.model.apply(params, x, training=training)

def create_network(hparams):
    return Wrapper(
        rank_k=int(hparams.get('rank_k', 48)),
        hidden_size=int(hparams.get('hidden_size', 64)),
        normalize_loadings=bool(hparams.get('normalize_loadings', True))
    )

def compute_loss(predictions, targets, params, x):
    """
    Horizon-weighted MAE to emphasize longer horizons while preserving scale.
    Weights increase linearly from 0.9 to 1.3 and are normalized to mean=1.
    Also adds a tiny L2 on loadings for scale stability.
    """
    T = predictions.shape[1]
    w = jnp.linspace(0.9, 1.3, T)
    w = w / jnp.mean(w)
    mae = jnp.mean(jnp.abs(predictions - targets) * w[None, :, None])

    # Tiny L2 on loadings (kept very small to avoid hurting performance)
    lam_l2 = 1e-7
    if isinstance(params, dict) and 'params' in params:
        p = params['params']
    else:
        p = params
    L = p.get('loadings', None)
    if L is not None:
        mae = mae + lam_l2 * jnp.mean(L * L)

    return mae

def create_optimizer(learning_rate: float = 0.001):
    # Global-norm clipping for stability + Adam
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adam(learning_rate=learning_rate, eps=1e-8)
    )
